def rounded_avg(n, m):
    '''Returns the rounded average of two positive integers as a binary string. Rounds .5 up. Returns -1 for invalid inputs.'''
    if n <= 0 or m <= 0 or n > m:
        return -1
    total = n + m
    if total % 2 == 0:
        avg = total // 2
    else:
        avg = total // 2 + 1
    return format(avg, 'b')

